def find_index_of_boolean(list_, value):
    for i, item in enumerate(list_):
        if isinstance(item, bool) and item == value:
            return i
    return -1

# Example usage:
my_list = [True, False, True]
index = find_index_of_boolean(my_list, True)
print(index)  # Output: 1

code_base:
To find the index of an integer in a list where the integer is a boolean, you can use the `index()` method in Python. This method returns the first occurrence of the specified value in the list. If the value is not found, it raises a `ValueError`. Here's how you can do it:

```python
def find_boolean_index(lst, value):
    try:
        return lst.index(value)
    except ValueError:
        return None

# Example usage:
my_list = [1, 2, True, 3, False]
index = find_boolean_index(my_list, True)
print(index)  # Output

import os

def choose_random_file(directory):
    # List all files in the directory
    files = os.listdir(directory)
    # Select a random file
    return os.path.join(directory, files[random.randint(0, len(files))])
